#!/bin/bashset -euo pipefail# =============================================================================# Usage# =============================================================================## bash cluster/submit_openmm_job.sh \#     path/to/generated_openmm_script.py## =============================================================================if [[ $# -ne 1 ]]; then    echo "Usage:"    echo "  $0 <generated_openmm_script.py>"    exit 1fi# =============================================================================# Resolve repository and script paths# =============================================================================LAUNCHER_DIRECTORY="$(    cd "$(dirname "${BASH_SOURCE[0]}")"    pwd)"PROJECT_ROOT="$(    cd "${LAUNCHER_DIRECTORY}/.."    pwd)"SIMULATION_SCRIPT="$(realpath "$1")"if [[ ! -f "$SIMULATION_SCRIPT" ]]; then    echo "Simulation script not found:"    echo "$SIMULATION_SCRIPT"    exit 1fiSCRIPT_NAME="$(basename "$SIMULATION_SCRIPT" .py)"SCRIPT_DIRECTORY="$(dirname "$SIMULATION_SCRIPT")"TIMESTAMP="$(date +"%Y%m%d_%H%M%S")"JOB_FILE="${SCRIPT_DIRECTORY}/${SCRIPT_NAME}_${TIMESTAMP}.job"SLURM_OUTPUT="${SCRIPT_DIRECTORY}/slurm_${SCRIPT_NAME}_%j.out"SLURM_ERROR="${SCRIPT_DIRECTORY}/slurm_${SCRIPT_NAME}_%j.err"IPHA_ENV="/scratch/s.983045/iphasimulator/envs/iphasimulator"IPHA_PYTHON="${IPHA_ENV}/bin/python"echoecho "Project root      : $PROJECT_ROOT"echo "Simulation script : $SIMULATION_SCRIPT"echo "Script directory  : $SCRIPT_DIRECTORY"echo "Job file          : $JOB_FILE"echo "Environment       : $IPHA_ENV"echo# =============================================================================# Write Slurm job# =============================================================================cat > "$JOB_FILE" << EOF#!/bin/bash --login#SBATCH --job-name=${SCRIPT_NAME}#SBATCH --account=scw1977#SBATCH --partition=accel_ai#SBATCH --nodes=1#SBATCH --ntasks=1#SBATCH --cpus-per-task=4#SBATCH --mem=96G#SBATCH --time=2-00:00#SBATCH --gres=gpu:1#SBATCH --output=${SLURM_OUTPUT}#SBATCH --error=${SLURM_ERROR}set -euo pipefailmodule purgemodule load mamba/4.14.0-0source activate "${IPHA_ENV}"export IPHASIMULATOR_PYTHON="${IPHA_PYTHON}"export PYTHONUNBUFFERED=1echo "============================================================"echo "iPHAsimulator OpenMM job"echo "============================================================"echo "Slurm job ID       : \$SLURM_JOB_ID"echo "Slurm node         : \$SLURMD_NODENAME"echo "Submission dir     : \$SLURM_SUBMIT_DIR"echo "Project root       : ${PROJECT_ROOT}"echo "Simulation script  : ${SIMULATION_SCRIPT}"echo "Python executable  : \$(which python)"echo "Python version     : \$(python --version)"echo "Start time         : \$(date)"echo "============================================================"nvidia-smi || truecd "${PROJECT_ROOT}""${IPHA_PYTHON}" -u "${SIMULATION_SCRIPT}"echoecho "============================================================"echo "Simulation finished successfully"echo "End time: \$(date)"echo "============================================================"EOFchmod +x "$JOB_FILE"echo "Submitting job..."sbatch "$JOB_FILE"